@msig trait AssessmentDecision_battery_assessment_process_assessment_decision_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_assessment_decision)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_assessment_decision)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_assessment_decision)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_assessment_decision)
  }

  /** helper function to set the values of all input ports.
   * @param assessment_context payload for data port assessment_context
   * @param qualified_evidence payload for data port qualified_evidence
   */
  def put_concrete_inputs(assessment_context : Battery_Status_Assessment_Service.AssessmentContext.Type,
                          qualified_evidence : Battery_Status_Assessment_Service.TaggedQualifiedEvidence): Unit = {
    put_assessment_context(assessment_context)
    put_qualified_evidence(qualified_evidence)
  }


  /** helper function to check AssessmentDecision_battery_assessment_process_assessment_decision's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param decision_assessment method that will be called with the value of the outgoing data
   *        port 'decision_assessment'.
   */
  def check_concrete_output(decision_assessment: Battery_Status_Assessment_Service.TaggedAssessment => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val decision_assessmentValue: Battery_Status_Assessment_Service.TaggedAssessment = get_decision_assessment().get
    if(!decision_assessment(decision_assessmentValue)) {
      testFailures = testFailures :+ st"'decision_assessment' did not match expected: value of the outgoing data port is ${decision_assessmentValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_assessment_context(value : Battery_Status_Assessment_Service.AssessmentContext.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_assessment_decision.operational_api.assessment_context_Id, Battery_Status_Assessment_Service.AssessmentContext_Payload(value))
  }

  // setter for in DataPort
  def put_qualified_evidence(value : Battery_Status_Assessment_Service.TaggedQualifiedEvidence): Unit = {
    Art.insertInInfrastructurePort(Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_assessment_decision.operational_api.qualified_evidence_Id, Battery_Status_Assessment_Service.TaggedQualifiedEvidence_Payload(value))
  }

  // getter for out DataPort
  def get_decision_assessment(): Option[Battery_Status_Assessment_Service.TaggedAssessment] = {
    val value: Option[Battery_Status_Assessment_Service.TaggedAssessment] = get_decision_assessment_payload() match {
      case Some(Battery_Status_Assessment_Service.TaggedAssessment_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port decision_assessment.  Expecting 'Battery_Status_Assessment_Service.TaggedAssessment_Payload' but received ${v}")
      case _ => None[Battery_Status_Assessment_Service.TaggedAssessment]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_decision_assessment_payload(): Option[Battery_Status_Assessment_Service.TaggedAssessment_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.BatteryStatusAssessmentServiceSystem_Instance_battery_assessment_process_assessment_decision.initialization_api.decision_assessment_Id).asInstanceOf[Option[Battery_Status_Assessment_Service.TaggedAssessment_Payload]]
  }

}
